import ast
import sys
try:
    from hae.evaluation.harness import ExecutionHarness
    import inspect
    src = inspect.getsource(ExecutionHarness._gate_smoke)
except Exception:
    print('IMPORT_FAIL')
    sys.exit(0)
lines = src.splitlines()
indent_stack = []
assign_lines = []
use_lines = []
for i, line in enumerate(lines):
    stripped = line.strip()
    if not stripped or stripped.startswith('#'): continue
    indent = len(line) - len(line.lstrip())
    while indent_stack and indent_stack[-1][0] >= indent:
        indent_stack.pop()
    if 'e =' in stripped or 'e=' in stripped:
        if 'except' not in stripped and 'as e' not in stripped:
            assign_lines.append((i, indent))
    if 'e' in stripped and ('e.' in stripped or 'e)' in stripped or 'e,' in stripped):
        if 'except' not in stripped:
            use_lines.append((i, indent))
if assign_lines and use_lines:
    print('MECHANISM_CONFIRMED')
else:
    print('MECHANISM_NOT_FOUND')

